package systemx_test

import (
	"os"
	"testing"

	"github.com/egdaemon/eg/internal/systemx"
	"github.com/stretchr/testify/require"
)

// DO NOT EDIT: This file was auto generated by egautotest.

func TestWorkingDirectoryOrDefault(t *testing.T) {
	t.Run("returns the current working directory", func(t *testing.T) {
		wd, err := os.Getwd()
		require.NoError(t, err)
		require.Equal(t, wd, systemx.WorkingDirectoryOrDefault("fallback"))
	})

	t.Run("returns the fallback when the working directory cannot be determined", func(t *testing.T) {
		origWd, err := os.Getwd()
		require.NoError(t, err)

		dir := t.TempDir()
		require.NoError(t, os.Chdir(dir))
		t.Cleanup(func() { _ = os.Chdir(origWd) })

		require.NoError(t, os.RemoveAll(dir))
		require.Equal(t, "fallback", systemx.WorkingDirectoryOrDefault("fallback"))
	})
}
